content:
{
  "code": ":root {
  --color-bg: #ffffff;
  --color-text-primary: #111111;
  --color-text-secondary: #666666;
  --color-border: #e0e0e0;
  --color-pill-bg: #f5f5f5;
  --color-pill-active-bg: #111111;
  --color-pill-active-text: #ffffff;
  --color-row-bg: #fafafa;
  --color-btn-disabled-bg: #e0e0e0;
  --color-btn-disabled-text: #999999;

  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";

  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-pill: 999px;

  --max-width: 430px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
  color: var(--color-text-primary);
  background-color: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#app {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: var(--space-lg) var(--space-md);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

.header {
  margin-bottom: var(--space-lg);
  text-align: center;
}

#page-title {
  font-size: 24px;
  font-weight: 700;
  margin: 0;
  letter-spacing: -0.02em;
}

.destination-pills {
  display: flex;
  justify-content: center;
  gap: var(--space-sm);
  margin-bottom: var(--space-lg);
}

.pill {
  padding: var(--space-xs) var(--space-md);
  border-radius: var(--radius-pill);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  border: none;
  background-color: var(--color-pill-bg);
  color: var(--color-text-primary);
  transition: background-color 0.2s, color 0.2s;
}

.pill[disabled] {
  opacity: 0.6;
  cursor: default;
}

.pill.active {
  background-color: var(--color-pill-active-bg);
  color: var(--color-pill-active-text);
}

#itinerary-list {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}

.day-heading {
  font-size: 16px;
  font-weight: 600;
  margin: 0 0 var(--space-sm) 0;
  color: var(--color-text-secondary);
}

.place-row {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  background-color: var(--color-row-bg);
  border-radius: var(--radius-md);
  padding: var(--space-sm);
  border: 1px solid transparent;
}

.checkbox-wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.checkbox-wrapper input[type="checkbox"] {
  width: 20px;
  height: 20px;
  cursor: pointer;
  accent-color: var(--color-text-primary);
}

.place-media {
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  background-color: #eee;
}

.place-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.place-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.place-name {
  font-size: 15px;
  font-weight: 600;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.place-meta {
  font-size: 12px;
  color: var(--color-text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.reorder-handle {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  cursor: grab;
  padding: var(--space-xs);
  opacity: 0.5;
}

.reorder-handle[disabled] {
  cursor: default;
  opacity: 0.3;
}

.reorder-handle img {
  pointer-events: none;
}

.action-footer {
  margin-top: var(--space-lg);
  padding-top: var(--space-md);
  border-top: 1px solid var(--color-border);
}

.btn-primary {
  width: 100%;
  padding: var(--space-md);
  font-size: 16px;
  font-weight: 600;
  color: #ffffff;
  background-color: var(--color-text-primary);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
}

.btn-primary[disabled] {
  background-color: var(--color-btn-disabled-bg);
  color: var(--color-btn-disabled-text);
  cursor: not-allowed;
}"
}
